import test from 'node:test';
import assert from 'node:assert/strict';
import { listProducts, getProduct } from '../src/catalogue.js';

test('every product has a whole-cent price and a known VAT rate', () => {
  for (const p of listProducts()) {
    assert.ok(Number.isInteger(p.unitPrice) && p.unitPrice > 0, p.sku);
    assert.ok([0, 9, 21].includes(p.vatRate), p.sku);
  }
});

test('getProduct finds a product by SKU', () => {
  const r = getProduct('DES-HOUR');
  assert.equal(r.ok, true);
  assert.equal(r.value.unitPrice, 8500);
});

test('getProduct reports an unknown SKU', () => {
  assert.deepEqual(getProduct('NOPE'), { ok: false, error: 'UNKNOWN_SKU' });
});

test('listProducts returns copies', () => {
  listProducts()[0].unitPrice = 1;
  assert.equal(getProduct('DES-HOUR').value.unitPrice, 8500);
});

